window.TRILHA_GOLD_BANKS=window.TRILHA_GOLD_BANKS||{};window.TRILHA_GOLD_BANKS["v5-sc-A8"]={"id":"sc-A8","title":"Cetoacidose diabética pediátrica | 30 questões clínicas autorais","group":"P2 • Saúde da Criança II","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","version":"5.1.0","questions":[{"id":"ouro-rigor5-sc-A8-01","topicId":"sc-A8","stem":"Menina de 11 anos apresenta poliúria, polidipsia, vômitos, respiração profunda e glicemia 425 mg/dL. Gasometria venosa: pH 7,17, bicarbonato 10 mEq/L; beta-hidroxibutirato sanguíneo elevado. Qual síndrome une os dados?","options":["Hiperglicemia isolada sem cetose, porque o bicarbonato é compatível com alcalose.","Estado hiperosmolar isolado, pois toda glicemia >400 exclui cetose.","Acidose respiratória primária pela respiração profunda e rápida.","Cetoacidose diabética: hiperglicemia, cetose e acidose metabólica.","Cetose de jejum normoglicêmica sem diabetes."],"answer":3,"analysis":["INCORRETA. O bicarbonato de 10 indica acidose importante.","INCORRETA. A cetose e acidose estão presentes.","INCORRETA. A gasometria demonstra bicarbonato baixo, com compensação respiratória.","CORRETA. A tríade hiperglicemia, cetonemia e acidose metabólica define o quadro clássico de CAD.","INCORRETA. Glicemia de 425 e quadro clínico não são compatíveis com jejum simples."],"explanation":"A tríade hiperglicemia, cetonemia e acidose metabólica define o quadro clássico de CAD.","memorizar":"CAD = HIPERGLICEMIA + CETOSE + ACIDOSE METABÓLICA.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"triângulo diagnóstico CAD","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"moderada"},{"id":"ouro-rigor5-sc-A8-02","topicId":"sc-A8","stem":"Menino de 12 anos chega taquipneico com incursões respiratórias amplas, hálito cetônico e SpO₂ 98% em ar ambiente. Gasometria mostra bicarbonato 7 mEq/L e pCO₂ baixa. Qual é a explicação fisiológica da respiração?","options":["Falência respiratória hipercápnica primária, que explica pCO₂ baixa por retenção de CO₂.","Hiperventilação compensatória da acidose metabólica.","Broncoespasmo com hipoventilação alveolar, comprovado pelo bicarbonato baixo.","Alcalose metabólica compensada com produção de cetonas.","Hiperventilação psicogênica primária obrigatória porque saturação é normal."],"answer":1,"analysis":["INCORRETA. Retenção produziria pCO₂ elevada, não reduzida.","CORRETA. A respiração de Kussmaul reflete compensação respiratória intensa para excesso de ácidos metabólicos.","INCORRETA. Não há dado de obstrução; ventilação é aumentada como compensação.","INCORRETA. Bicarbonato muito baixo indica acidose.","INCORRETA. A gasometria mostra causa metabólica clara."],"explanation":"A respiração de Kussmaul reflete compensação respiratória intensa para excesso de ácidos metabólicos.","memorizar":"KUSSMAUL = compensação RESPIRATÓRIA de ACIDOSE METABÓLICA.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"respiração de Kussmaul","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sc-A8-03","topicId":"sc-A8","stem":"Adolescente com CAD tem potássio sérico 5,3 mEq/L antes da insulina, diurese osmótica intensa e vômitos há 24 horas. Qual aspecto eletrolítico deve orientar o seguimento?","options":["Potássio total normal por definição, porque o exame sérico está acima de 5.","Hipercalemia inicial garante que nenhum potássio será necessário durante a terapia.","A perda urinária osmótica aumenta o estoque intracelular de potássio.","A acidose transfere todo o potássio para dentro das células.","Estoque corporal de potássio reduzido apesar de potassemia inicial alta."],"answer":4,"analysis":["INCORRETA. Potassemia reflete concentração, não estoque total.","INCORRETA. Insulina pode reduzir potássio rapidamente.","INCORRETA. Diurese favorece perda corporal.","INCORRETA. Na CAD, insulinopenia e acidose favorecem elevação extracelular.","CORRETA. Deficiência de insulina e acidose deslocam potássio ao extracelular enquanto diurese e perdas gastrointestinais reduzem o estoque corporal."],"explanation":"Deficiência de insulina e acidose deslocam potássio ao extracelular enquanto diurese e perdas gastrointestinais reduzem o estoque corporal.","memorizar":"CAD pode ter K sérico ALTO com DEPÓSITO TOTAL BAIXO.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"déficit total de potássio","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A8-04","topicId":"sc-A8","stem":"Criança de 9 anos com CAD apresenta potássio 2,8 mEq/L e alterações de repolarização no ECG. Há perfusão restaurada e plano de iniciar insulina IV. Qual prioridade modifica a sequência?","options":["Corrigir a hipocalemia antes de iniciar insulina.","Iniciar insulina em bolus para elevar imediatamente potássio sérico.","Administrar bicarbonato como substituto para potássio, pois ele mantém potássio extracelular.","Desconsiderar ECG e iniciar rotina de insulina porque potássio baixo não afeta o coração.","Prescrever apenas dieta rica em potássio oral à criança vomitando, sem monitorização."],"answer":0,"analysis":["CORRETA. Insulina dirige potássio ao interior celular e pode agravar hipocalemia já presente.","INCORRETA. Insulina reduz potassemia.","INCORRETA. Bicarbonato pode agravar queda do potássio.","INCORRETA. Hipocalemia causa arritmias.","INCORRETA. A urgência requer correção monitorada e apropriada."],"explanation":"Insulina dirige potássio ao interior celular e pode agravar hipocalemia já presente.","memorizar":"K MUITO BAIXO ANTES INSULINA: REPOR PRIMEIRO conforme protocolo.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"hipocalemia antes da insulina","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A8-05","topicId":"sc-A8","stem":"Menina de 7 anos com CAD moderada e taquicardia apresenta sinais de desidratação, mas sem hipotensão ou choque. A equipe avalia começar hidratação. Qual princípio é mais apropriado?","options":["Repor todo o déficit de água em poucos minutos com solução hipotônica.","Evitar qualquer hidratação até a glicemia chegar a 200 mg/dL.","Hidratar com solução isotônica e plano individualizado, com monitorização.","Utilizar glicose hipertônica como fluido principal sem considerar hipovolemia.","Tratar apenas com insulina subcutânea apesar de desidratação clinicamente relevante."],"answer":2,"analysis":["INCORRETA. Correção brusca e solução hipotônica inicial são inadequadas.","INCORRETA. Desidratação precisa ser tratada no início.","CORRETA. Hidratação corrige hipovolemia e perfusão renal, mas deve considerar gravidade, perdas e evolução para evitar extremos.","INCORRETA. Glicose concentrada não repõe de modo adequado o volume circulante.","INCORRETA. Reposição de fluido é componente essencial da CAD."],"explanation":"Hidratação corrige hipovolemia e perfusão renal, mas deve considerar gravidade, perdas e evolução para evitar extremos.","memorizar":"CAD: REPOSIÇÃO ISOTÔNICA planejada + monitorização.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"reidratação inicial","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sc-A8-06","topicId":"sc-A8","stem":"Adolescente com CAD tem PA 75/40 mmHg, extremidades frias, pulsos finos e confusão. A gasometria mostra acidose, mas perfusão está criticamente comprometida. Qual é a prioridade inicial?","options":["Priorizar insulina em bolus antes de avaliar hipoperfusão, porque a glicemia é o único problema urgente.","Administrar solução hipotônica como ressuscitação de escolha.","Interpretar PA 75/40 como compensada porque há taquicardia.","Esperar exame de urina completo antes de qualquer suporte circulatório.","Restaurar perfusão com cristalóide isotônico, reavaliando choque."],"answer":4,"analysis":["INCORRETA. Choque ameaça órgãos e demanda reposição/monitorização.","INCORRETA. Solução isotônica é preferida para expansão inicial.","INCORRETA. A PA e demais sinais apontam choque descompensado.","INCORRETA. Ressuscitação não depende da urina.","CORRETA. Choque exige restauração rápida da perfusão e avaliação da causa, mesmo em paciente com CAD."],"explanation":"Choque exige restauração rápida da perfusão e avaliação da causa, mesmo em paciente com CAD.","memorizar":"CAD COM CHOQUE: restaurar PERFUSÃO antes de fixar na glicose.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"choque associado à CAD","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A8-07","topicId":"sc-A8","stem":"Menino de 10 anos estabilizado com fluidoterapia inicial por CAD tem potássio seguro para insulinoterapia. Um profissional propõe bolus IV de insulina, seguido de infusão. Qual ajuste costuma ser recomendado em protocolos pediátricos?","options":["Iniciar infusão de insulina sem bolus IV rotineiro.","Usar bolus IV obrigatório em toda CAD pediátrica para acelerar queda de glicemia.","Suspender permanentemente a insulina até cetonemia negativa apenas com fluidos.","Dar insulina apenas quando houver alcalose, não acidose.","Usar só correção subcutânea de 24/24 h enquanto permanece acidótico grave."],"answer":0,"analysis":["CORRETA. Na CAD pediátrica, bolus não é habitualmente recomendado; correção contínua e monitorada reduz alterações abruptas desnecessárias.","INCORRETA. Bolus inicial não é rotina em pediatria.","INCORRETA. A insulinoterapia é necessária para suprimir cetogênese.","INCORRETA. Insulina trata a causa metabólica da cetoacidose.","INCORRETA. A necessidade de infusão depende de gravidade e protocolo."],"explanation":"Na CAD pediátrica, bolus não é habitualmente recomendado; correção contínua e monitorada reduz alterações abruptas desnecessárias.","memorizar":"CAD pediátrica: INSULINA contínua, SEM BOLUS inicial rotineiro.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"insulina sem bolus rotineiro","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sc-A8-08","topicId":"sc-A8","stem":"Criança em infusão de insulina por CAD teve glicemia reduzida de 480 para 210 mg/dL. Entretanto, pH é 7,22, ânion gap permanece elevado e beta-hidroxibutirato está alto. Qual decisão é correta?","options":["Suspender insulina porque glicemia abaixo de 250 significa CAD resolvida.","Administrar apenas bicarbonato para fechar gap sem continuar insulina.","Retirar monitoração de eletrólitos assim que glicemia cai.","Manter insulina para corrigir cetose e acrescentar dextrose à hidratação.","Interpretar ânion gap alto como dado sem relevância na CAD."],"answer":3,"analysis":["INCORRETA. Cetose e acidose persistem.","INCORRETA. A interrupção da cetogênese depende de insulina.","INCORRETA. Insulina e fluidos ainda alteram eletrólitos.","CORRETA. A normalização da glicemia não indica fechamento do gap; a insulina é necessária até resolução da acidose cetótica.","INCORRETA. Gap ajuda a acompanhar acidose cetótica."],"explanation":"A normalização da glicemia não indica fechamento do gap; a insulina é necessária até resolução da acidose cetótica.","memorizar":"GLICOSE CAI ANTES do GAP: manter INSULINA e adicionar DEXTROSE conforme necessário.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"glicose normaliza antes cetose","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A8-09","topicId":"sc-A8","stem":"Adolescente com CAD melhora clinicamente após tratamento. Beta-hidroxibutirato sérico diminuiu muito e ânion gap fechou, porém teste urinário por nitroprussiato segue marcando cetonas. Qual explicação é plausível?","options":["Cetonúria persistente sempre prova piora da acidose, mesmo com gap fechado.","Nitroprussiato detecta acetoacetato, não beta-hidroxibutirato.","Beta-hidroxibutirato não participa da CAD e não deve ser medido.","Nitroprussiato mede exclusivamente glicemia, não cetonas.","Mudança de cetonúria significa obrigatoriamente insuficiência renal aguda."],"answer":1,"analysis":["INCORRETA. Método não acompanha todas as cetonas de modo proporcional.","CORRETA. O método urinário não mede diretamente beta-hidroxibutirato; mudança da razão entre cetonas pode produzir aparente persistência.","INCORRETA. É cetona predominante na CAD grave.","INCORRETA. Reação mede corpos cetônicos específicos.","INCORRETA. Exame deve ser interpretado com ácido-base e cetonemia."],"explanation":"O método urinário não mede diretamente beta-hidroxibutirato; mudança da razão entre cetonas pode produzir aparente persistência.","memorizar":"NITROPRUSSIATO urinário ≠ beta-hidroxibutirato; monitorar GAP e CETONEMIA.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"cetonúria e beta-hidroxibutirato","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A8-10","topicId":"sc-A8","stem":"Menina de 8 anos em tratamento para CAD desenvolve cefaleia de novo início, bradicardia relativa, queda progressiva do nível de consciência e vômitos após período de melhora. Qual complicação exige intervenção urgente?","options":["Resolução da acidose comprovada pela bradicardia e vômitos.","Hipoglicemia presumida como única explicação, sem medir glicose nem considerar outras causas.","Suspeitar de lesão cerebral associada à CAD e agir rapidamente.","Enxaqueca primária definida porque houve cefaleia.","Efeito inevitável de insulina que dispensa exame neurológico seriado."],"answer":2,"analysis":["INCORRETA. Deterioração neurológica é de alarme, não de recuperação.","INCORRETA. Glicose deve ser verificada, mas lesão cerebral é diferencial crítico.","CORRETA. Deterioração neurológica durante CAD é sinal de emergência e pode preceder achados de neuroimagem.","INCORRETA. O contexto CAD e rebaixamento exige investigação urgente.","INCORRETA. Monitorização neurológica é central na CAD pediátrica."],"explanation":"Deterioração neurológica durante CAD é sinal de emergência e pode preceder achados de neuroimagem.","memorizar":"CAD + PIORA NEUROLÓGICA: SUSPEITAR DE LESÃO CEREBRAL e tratar urgente.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"edema cerebral: sinais clínicos","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A8-11","topicId":"sc-A8","stem":"Menina de 12 anos com glicemia 620 mg/dL apresenta sódio medido de 127 mEq/L. Sem sinais de sobrecarga, um colega diagnostica hiponatremia hipotônica grave e propõe correção agressiva de sódio sem cálculos. Qual passo melhora a interpretação?","options":["Usar somente sódio medido e ignorar glicose, porque osmolaridade não influencia a leitura.","Calcular o sódio corrigido pela hiperglicemia e acompanhar tendência.","Corrigir sódio com base apenas na idade, pois a glicose não interfere.","Diagnosticar SIADH definitivo por sódio 127, sem avaliar hidratação e glicemia.","Concluir hipernatremia verdadeira porque o paciente está desidratado."],"answer":1,"analysis":["INCORRETA. Hiperglicemia altera a distribuição de água.","CORRETA. Glicose extracelular elevada desloca água para fora das células, reduzindo sódio sérico aparente; sódio corrigido orienta osmolaridade.","INCORRETA. O impacto osmótico de glicemia precisa ser integrado.","INCORRETA. Sódio reduzido em hiperglicemia tem mecanismo alternativo.","INCORRETA. Desidratação não define valor corrigido sem cálculo."],"explanation":"Glicose extracelular elevada desloca água para fora das células, reduzindo sódio sérico aparente; sódio corrigido orienta osmolaridade.","memorizar":"SÓDIO MEDIDO pode cair por HIPERGLICEMIA; usar SÓDIO CORRIGIDO.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"sódio corrigido","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A8-12","topicId":"sc-A8","stem":"Escolar com CAD tem Na 138, Cl 104 e bicarbonato 8 mEq/L. Qual conclusão decorre do cálculo clássico do ânion gap (sem potássio)?","options":["Ânion gap de 8, normal, pois corresponde só ao bicarbonato.","Ânion gap de 12, porque se subtrai apenas cloro do bicarbonato.","Ânion gap de 242, pela soma dos íons, demonstrando alcalose.","Ânion gap elevado de 26 mEq/L.","Ânion gap de 34 por somar sódio e bicarbonato, excluindo cloro."],"answer":3,"analysis":["INCORRETA. Gap não é igual ao bicarbonato isolado.","INCORRETA. A fórmula emprega Na menos soma Cl + HCO₃.","INCORRETA. Cálculo usa diferença, não soma.","CORRETA. Gap = Na − (Cl + HCO₃) = 138 − (104 + 8) = 26 mEq/L; os cetoácidos elevam o gap.","INCORRETA. O cloreto integra a fórmula."],"explanation":"Gap = Na − (Cl + HCO₃) = 138 − (104 + 8) = 26 mEq/L; os cetoácidos elevam o gap.","memorizar":"GAP = Na − Cl − HCO3; CAD costuma elevar GAP.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"ânion gap cálculo","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"moderada"},{"id":"ouro-rigor5-sc-A8-13","topicId":"sc-A8","stem":"Adolescente tratado para CAD passa a ter cetonemia quase normal e ânion gap fechado, porém bicarbonato ainda baixo e cloreto 116 mEq/L após uso prolongado de salina. Qual hipótese pode explicar parte da acidose persistente?","options":["Acidose hiperclorêmica de ânion gap normal na fase de recuperação.","CAD obrigatoriamente grave e inalterada porque todo bicarbonato baixo significa cetonemia alta.","Alcalose metabólica por aumento do cloro.","Acidose respiratória por pCO₂ reduzida, mesmo sem valor informado.","Hiperglicemia hiperosmolar isolada definida apenas por cloreto elevado."],"answer":0,"analysis":["CORRETA. Retenção relativa de cloro durante reposição pode gerar acidose sem elevação do gap, mesmo com resolução da cetogênese.","INCORRETA. Gap fechado e cetonemia baixa sugerem outra componente ácido-base.","INCORRETA. Cloro alto tende a reduzir diferença de íons fortes e bicarbonato.","INCORRETA. A alteração descrita é metabólica e cloreto elevada.","INCORRETA. Cloreto não define síndrome hiperosmolar."],"explanation":"Retenção relativa de cloro durante reposição pode gerar acidose sem elevação do gap, mesmo com resolução da cetogênese.","memorizar":"GAP FECHOU + CLORO ALTO + HCO3 baixo: considerar ACIDOSE HIPERCLORÊMICA.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"acidose hiperclorêmica na recuperação","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A8-14","topicId":"sc-A8","stem":"Menino de 10 anos com CAD e pH 7,05 apresenta ventilação compensatória efetiva e perfusão recuperada. Um profissional quer administrar bicarbonato por rotina para normalizar pH rapidamente. Qual princípio deve orientar a discussão?","options":["Corrigir todo pH abaixo de 7,30 com bicarbonato em bolus obrigatório.","Bicarbonato substitui insulina na supressão da lipólise.","Bicarbonato não é rotina na CAD pediátrica.","Bicarbonato sempre melhora potássio sérico em paciente hipocalêmico.","Usar bicarbonato até eliminar todas as cetonas sem monitorização."],"answer":2,"analysis":["INCORRETA. Bicarbonato não é tratamento padrão indiscriminado.","INCORRETA. A insulinoterapia bloqueia produção de cetonas.","CORRETA. Bicarbonato pode ter efeitos adversos e não corrige a causa da cetogênese; fluidos e insulina permanecem centrais.","INCORRETA. Pode agravar hipocalemia.","INCORRETA. Não é estratégia rotineira nem isenta de risco."],"explanation":"Bicarbonato pode ter efeitos adversos e não corrige a causa da cetogênese; fluidos e insulina permanecem centrais.","memorizar":"CAD pediátrica: NÃO dar BICARBONATO por rotina.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"bicarbonato na CAD","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A8-15","topicId":"sc-A8","stem":"Menina de 7 anos com diabetes recém-diagnosticado tem pH venoso 7,08, bicarbonato 8 mEq/L, glicemia 500 e cetonas elevadas. Os familiares perguntam sobre gravidade da acidose. Qual princípio é correto?","options":["A gravidade depende só de glicemia, e pH 7,08 não contribui.","Uma criança alerta nunca pode ter CAD grave pelo pH.","A presença de cetona urinária, independentemente do pH, define sempre gravidade igual.","pH baixo indica alcalose compensatória porque há Kussmaul.","Avaliar gravidade por pH e bicarbonato, além do quadro clínico."],"answer":4,"analysis":["INCORRETA. Acidemia e bicarbonato são essenciais.","INCORRETA. Estado de consciência pode variar apesar de acidose importante.","INCORRETA. Critérios metabólicos graduam intensidade.","INCORRETA. pH reduzido é acidemia.","CORRETA. Classificação da CAD incorpora pH e bicarbonato; glicemia isoladamente não estabelece gravidade."],"explanation":"Classificação da CAD incorpora pH e bicarbonato; glicemia isoladamente não estabelece gravidade.","memorizar":"CAD: classificar GRAVIDADE por pH/HCO3 e clínica, NÃO só glicemia.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"gravidade da CAD pelo pH","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sc-A8-16","topicId":"sc-A8","stem":"Menina de 4 anos após 36 horas de pouca ingestão tem glicemia 72 mg/dL, leve cetonemia e bicarbonato 19 mEq/L. Está alerta, bem perfundida e sem poliúria prévia. Qual hipótese explica melhor os dados?","options":["CAD clássica confirmada porque qualquer cetona positiva é suficiente.","Estado hiperosmolar hiperglicêmico por glicemia 72 mg/dL.","Cetose de jejum sem critérios de CAD hiperglicêmica clássica.","Intoxicação por salicilato obrigatória apenas por leve cetonemia.","Insuficiência renal crônica como única causa de cetose transitória."],"answer":2,"analysis":["INCORRETA. Falta hiperglicemia e acidose importante.","INCORRETA. A glicose não está elevada.","CORRETA. Jejum pode gerar cetonemia leve com normoglicemia e discreta alteração do bicarbonato, diferentemente da CAD clássica.","INCORRETA. Nenhuma exposição ou distúrbio misto foi descrito.","INCORRETA. Não há dados renais sustentando essa causa."],"explanation":"Jejum pode gerar cetonemia leve com normoglicemia e discreta alteração do bicarbonato, diferentemente da CAD clássica.","memorizar":"CETONA positiva isolada NÃO define CAD; integrar GLICEMIA e ACIDOSE.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"cetose de jejum versus CAD","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"moderada"},{"id":"ouro-rigor5-sc-A8-17","topicId":"sc-A8","stem":"Menino de 8 anos perdeu 6 kg em um mês, passou a urinar na cama, beber água continuamente e desenvolveu dor abdominal/vômitos. Exame demonstra desidratação e taquipneia profunda. Qual erro clínico é comum e perigoso?","options":["Investigar DM1/CAD, não atribuindo sintomas apenas à gastroenterite.","Considerar sinais crônicos de poliúria irrelevantes porque há vômito.","Interpretar taquipneia profunda exclusivamente como pneumonia sem integrar gasometria e glicemia.","Atribuir perda de peso ao crescimento esperado da faixa etária.","Descartar diabetes porque não há história familiar de tipo 1."],"answer":0,"analysis":["CORRETA. Poliúria, polidipsia, perda de peso e enurese nova precedendo vômitos apontam para deficiência de insulina.","INCORRETA. A cronologia de semanas é decisiva.","INCORRETA. Kussmaul sugere compensação de acidose.","INCORRETA. Perda ponderal acentuada em criança é sinal de alarme.","INCORRETA. DM1 pode ocorrer sem antecedente familiar."],"explanation":"Poliúria, polidipsia, perda de peso e enurese nova precedendo vômitos apontam para deficiência de insulina.","memorizar":"ENURESE NOVA + SEDE + EMAGRECIMENTO + VÔMITOS: pensar em DM1/CAD.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"CAD em diabetes recém-diagnosticado","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sc-A8-18","topicId":"sc-A8","stem":"Adolescente com DM1 usa bomba de insulina; após obstrução do cateter por 7 horas, desenvolve náuseas, hiperglicemia e beta-hidroxibutirato crescente. Qual mecanismo explica a evolução rápida?","options":["Infusão interrompida mantém insulina de ação longa por dias no subcutâneo.","Obstrução de cateter aumenta insulina circulante e produz hipoglicemia prolongada.","A cetonemia exclui falha de bomba porque só ocorre por infecção.","Lipólise diminui automaticamente quando insulina cessa.","Suspensão da basal pela bomba favorece cetogênese rápida."],"answer":4,"analysis":["INCORRETA. Bomba geralmente não oferece depósito basal de insulina longa.","INCORRETA. A interrupção reduz entrega de insulina.","INCORRETA. Deficiência de insulina é causa direta.","INCORRETA. Insulinopenia permite lipólise/cetogênese.","CORRETA. Bomba oferece insulina rápida sem depósito prolongado; falha de infusão deixa paciente sem basal efetiva."],"explanation":"Bomba oferece insulina rápida sem depósito prolongado; falha de infusão deixa paciente sem basal efetiva.","memorizar":"BOMBA PAROU = SEM INSULINA BASAL → risco rápido de CETONAS/CAD.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"falha bomba de insulina","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A8-19","topicId":"sc-A8","stem":"Adolescente obeso de 15 anos com diabetes conhecido apresenta glicemia 980 mg/dL, desidratação profunda, sonolência, osmolalidade efetiva elevada, pH 7,24 e cetonas elevadas. Qual estratégia de interpretação evita reducionismo?","options":["Escolher exclusivamente CAD porque osmolaridade elevada nunca ocorre com cetonas.","Considerar sobreposição entre CAD e estado hiperosmolar.","Escolher exclusivamente estado hiperosmolar porque pH <7,30 é irrelevante.","Classificar como hipoglicemia por sonolência.","Tratar como intoxicação alcoólica isolada porque há rebaixamento."],"answer":1,"analysis":["INCORRETA. Quadros podem se sobrepor.","CORRETA. Hiperglicemia/osmolalidade extremas com cetose e acidose pode representar características de ambas síndromes.","INCORRETA. Acidose e cetose indicam componente cetoacidótico.","INCORRETA. A glicemia está extremamente elevada.","INCORRETA. Os dados metabólicos sustentam descompensação diabética."],"explanation":"Hiperglicemia/osmolalidade extremas com cetose e acidose pode representar características de ambas síndromes.","memorizar":"HIPEROSMOLARIDADE MUITO ALTA + ACIDOSE/CETONAS: considerar SOBREPOSIÇÃO.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"sinais mistos CAD e hiperosmolar","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A8-20","topicId":"sc-A8","stem":"Menina com CAD tinha K 4,6 mEq/L antes da terapia. Duas horas após iniciar insulina, K está 3,2 mEq/L e ECG mostra onda U discreta. Qual mecanismo explica a queda?","options":["A insulina retira K das células e eleva sempre potassemia.","A correção da acidose impede qualquer mudança de potássio sérico.","A onda U é sinal específico de hipercalemia grave.","Insulina desloca K para as células e revela déficit corporal.","A queda sérica prova que não há perdas corporais prévias."],"answer":3,"analysis":["INCORRETA. O efeito predominante é entrada de K na célula.","INCORRETA. Potássio pode mudar rapidamente durante tratamento.","INCORRETA. Onda U sugere hipocalemia.","CORRETA. O potássio sérico cai com insulina e correção de acidose, exigindo monitorização e reposição conforme protocolo.","INCORRETA. Déficit total costuma ser relevante na CAD."],"explanation":"O potássio sérico cai com insulina e correção de acidose, exigindo monitorização e reposição conforme protocolo.","memorizar":"INSULINA → K ENTRA NA CÉLULA → HIPOCALEMIA pode surgir.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"potássio cai durante tratamento","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sc-A8-21","topicId":"sc-A8","stem":"Menino com CAD em resolução apresenta fósforo baixo, mas mantém força, respiração e função cardíaca normais. Não há hemólise ou hipoxemia persistente. Qual postura evita intervenção excessiva?","options":["Individualizar reposição de fosfato conforme gravidade/sintomas.","Reposição IV obrigatória em qualquer fósforo abaixo do limite, independentemente de sintomas.","Ignorar fósforo mesmo se houver insuficiência respiratória por fraqueza muscular.","Fosfato baixo prova hipercalcemia obrigatória e impede dosagem de cálcio.","Suspender insulina sempre que o fósforo se reduz discretamente."],"answer":0,"analysis":["CORRETA. Hipofosfatemia é comum na recuperação, porém reposição deve ser individualizada e monitorada.","INCORRETA. Reposição indiscriminada pode causar efeitos adversos.","INCORRETA. Hipofosfatemia importante pode afetar musculatura respiratória.","INCORRETA. Relação é complexa; cálcio deve ser monitorado quando se repõe.","INCORRETA. Insulina trata cetogênese; manejo deve considerar quadro global."],"explanation":"Hipofosfatemia é comum na recuperação, porém reposição deve ser individualizada e monitorada.","memorizar":"FOSFATO NA CAD: reposição SELETIVA, não automática.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"fosfato e reposição seletiva","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A8-22","topicId":"sc-A8","stem":"Adolescente com CAD tem gap fechado, boa aceitação oral, consciência normal e hidratação corrigida. Equipe planeja interromper infusão de insulina IV e iniciar esquema subcutâneo. Qual princípio previne recaída?","options":["Desligar infusão e só aplicar insulina subcutânea horas depois, quando a glicemia subir.","Manter infusão para sempre mesmo com recuperação e alimentação.","Trocar por antidiabético oral isolado em criança com DM1 sem avaliar necessidade de insulina.","Usar apenas hidratação por via oral e omitir insulina após fechar gap.","Sobrepor insulina subcutânea antes de interromper infusão IV."],"answer":4,"analysis":["INCORRETA. Lacuna de insulina favorece recidiva metabólica.","INCORRETA. Transição é possível quando CAD resolvida.","INCORRETA. DM1 exige insulina basal apropriada.","INCORRETA. A deficiência de insulina de base persiste.","CORRETA. Insulina IV tem meia-vida curta; desligá-la sem cobertura subcutânea efetiva pode permitir retorno da cetogênese."],"explanation":"Insulina IV tem meia-vida curta; desligá-la sem cobertura subcutânea efetiva pode permitir retorno da cetogênese.","memorizar":"TRANSIÇÃO IV → SC: SOBREPOR para não deixar BURACO DE INSULINA.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"transição insulina subcutânea","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A8-23","topicId":"sc-A8","stem":"Menina de 13 anos com CAD apresenta dor abdominal difusa e vômitos, sem sinais de peritonite, com pH 7,11. Após correção metabólica, a dor melhora substancialmente. Qual explicação é plausível?","options":["A dor abdominal prova apendicite mesmo quando desaparece com correção da acidose.","Toda dor em CAD é psicológica e dispensa reexame.","Acidose cetótica pode causar dor; reexaminar se persistir.","A acidose não provoca sintomas digestivos, então dor é sempre doença cirúrgica.","Vômitos excluem diabetes tipo 1 como diagnóstico inicial."],"answer":2,"analysis":["INCORRETA. Evolução metabólica deve ser integrada ao exame seriado.","INCORRETA. Abdome agudo pode coexistir e precisa de vigilância.","CORRETA. CAD pode mimetizar abdome agudo, mas a melhora após correção favorece mecanismo metabólico.","INCORRETA. Dor e vômitos são frequentes na CAD.","INCORRETA. CAD frequentemente apresenta vômitos."],"explanation":"CAD pode mimetizar abdome agudo, mas a melhora após correção favorece mecanismo metabólico.","memorizar":"CAD pode PARECER ABDOME AGUDO, mas REEXAMINAR se dor persiste.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"vômitos e dor abdominal","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sc-A8-24","topicId":"sc-A8","stem":"Adolescente com glicemia de 500 mg/dL tem poliúria intensa, sede e sinais de desidratação apesar de ingestão hídrica elevada. Qual mecanismo renal é central?","options":["Reabsorção ilimitada de toda glicose filtrada, sem qualquer glicosúria.","Diurese osmótica por glicosúria excedendo capacidade tubular.","Secreção de ADH abolida como único mecanismo para poliúria em CAD.","Filtração glomerular sempre nula em qualquer hiperglicemia.","Insulina elevada produz diurese osmótica ao aumentar glicosúria."],"answer":1,"analysis":["INCORRETA. Há limiar/capacidade tubular para reabsorção.","CORRETA. Glicose no túbulo renal retém água no lúmen, aumentando volume urinário e perda de solutos.","INCORRETA. A glicosúria osmótica é mecanismo dominante.","INCORRETA. A poliúria implica produção urinária relevante.","INCORRETA. Deficiência de insulina causa hiperglicemia na CAD."],"explanation":"Glicose no túbulo renal retém água no lúmen, aumentando volume urinário e perda de solutos.","memorizar":"HIPERGLICEMIA → GLICOSÚRIA → DIURESE OSMÓTICA → DESIDRATAÇÃO.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"diurese osmótica","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sc-A8-25","topicId":"sc-A8","stem":"Menino de 9 anos com DM1 omitiu insulina por um dia. Evolui com aumento de corpos cetônicos apesar de não ter ingerido alimentos gordurosos. Qual via metabólica explica a cetonemia?","options":["Absorção intestinal direta de cetonas de alimentos gordurosos é mecanismo obrigatório.","Excesso de insulina estimula lipólise e cetogênese em DM1 descompensado.","A ausência de ingestão de gordura exclui formação de corpos cetônicos.","Insulinopenia estimula lipólise e cetogênese hepática.","O glucagon não participa das respostas contrarregulatórias da insulinopenia."],"answer":3,"analysis":["INCORRETA. Cetonas são produzidas endogenamente pelo fígado.","INCORRETA. Insulina inibe lipólise e cetogênese.","INCORRETA. Reservas adiposas fornecem substratos.","CORRETA. Baixa insulina permite liberação de ácidos graxos e produção hepática de corpos cetônicos, gerando acidose.","INCORRETA. A relação insulina/glucagon é importante."],"explanation":"Baixa insulina permite liberação de ácidos graxos e produção hepática de corpos cetônicos, gerando acidose.","memorizar":"SEM INSULINA → LIPÓLISE + CETOGÊNESE HEPÁTICA.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"cetogênese e insulinopenia","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sc-A8-26","topicId":"sc-A8","stem":"Menino com CAD inicialmente Kussmaul apresenta redução progressiva da frequência respiratória, respirações superficiais e sonolência após deterioração hemodinâmica. CO₂ sobe e pH cai. Qual mudança fisiológica ocorreu?","options":["Melhora da CAD comprovada por menos esforço respiratório, mesmo com CO₂ em ascensão.","Falência da compensação ventilatória com retenção adicional de CO₂.","Correção total da acidose metabólica, porque a FR ficou menor.","Alcalose respiratória intensa com retenção de CO₂.","Hiperventilação alveolar crescente, apesar de movimentos superficiais e CO₂ elevado."],"answer":1,"analysis":["INCORRETA. A redução do drive com hipercapnia pode indicar exaustão.","CORRETA. A queda da ventilação alveolar impede eliminação compensatória de CO₂, agravando acidemia.","INCORRETA. pH piorou e HCO₃ não foi normalizado.","INCORRETA. Retenção causa acidose respiratória.","INCORRETA. CO₂ alto sugere ventilação alveolar insuficiente."],"explanation":"A queda da ventilação alveolar impede eliminação compensatória de CO₂, agravando acidemia.","memorizar":"CAD: KUSSMAUL COMPENSA; HIPOVENTILAÇÃO depois = FALÊNCIA.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"acidose versus hipoventilação","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A8-27","topicId":"sc-A8","stem":"Adolescente com DM1 e pneumonia chega em CAD após omitir doses de insulina por mal-estar. Um colega afirma que infecção não altera necessidade de insulina. Qual fisiopatologia corrige a afirmação?","options":["Infecção sempre reduz cortisol e catecolaminas, evitando hiperglicemia.","Omissão de insulina em doença febril protege contra acidose metabólica.","Resposta contrarreguladora à infecção favorece CAD por insulinopenia.","Citocinas não têm relação com sensibilidade insulínica ou metabolismo.","A pneumonia prova que não existe CAD, pois são diagnósticos mutuamente exclusivos."],"answer":2,"analysis":["INCORRETA. Estresse infeccioso estimula respostas contrarregulatórias.","INCORRETA. Insulinopenia favorece cetogênese.","CORRETA. Infecção aumenta demanda insulinotrópica e pode precipitar descompensação, especialmente com interrupção da terapia.","INCORRETA. Inflamação pode induzir resistência periférica.","INCORRETA. Podem coexistir e se precipitar."],"explanation":"Infecção aumenta demanda insulinotrópica e pode precipitar descompensação, especialmente com interrupção da terapia.","memorizar":"INFECÇÃO + INSULINA INSUFICIENTE → risco de CAD.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"infecção precipitante","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sc-A8-28","topicId":"sc-A8","stem":"Paciente de 12 anos em CAD grave tem glicemia muito alta e sódio corrigido acompanhado ao longo da terapia. A equipe debate por que alterações de osmolaridade precisam ser monitoradas. Qual princípio é correto?","options":["A osmolaridade plasmática é constante porque glicose não participa de sua determinação.","A troca de água entre compartimentos independe de gradientes osmóticos.","Sódio corrigido só importa depois da alta, não durante terapia.","Monitorar mudanças de tonicidade e risco neurológico.","Mudanças de tonicidade alteram apenas pele e nunca o cérebro."],"answer":3,"analysis":["INCORRETA. Glicose contribui à osmolaridade efetiva.","INCORRETA. A osmose é determinante de fluxos de água.","INCORRETA. Evolução da tonicidade orienta monitorização.","CORRETA. Durante reidratação/insulina, a tonicidade muda; vigilância clínica e bioquímica é necessária para evitar mudanças descontroladas.","INCORRETA. Tecido cerebral é sensível a mudanças osmóticas."],"explanation":"Durante reidratação/insulina, a tonicidade muda; vigilância clínica e bioquímica é necessária para evitar mudanças descontroladas.","memorizar":"CAD: monitorar TONICIDADE e estado NEUROLÓGICO durante tratamento.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"riscos da queda osmolar","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A8-29","topicId":"sc-A8","stem":"Menina de 11 anos em tratamento de CAD estabilizou PA e glicemia, mas recebe infusão de insulina e fluidos. Qual conjunto de parâmetros permite detectar complicações antes de ocorrer deterioração?","options":["Apenas peso corporal diário, pois eletrólitos se normalizam sem acompanhamento.","Somente glicemia, porque pH e cetonemia não importam após iniciar insulina.","Apenas oximetria, porque SpO₂ substitui eletrólitos e estado ácido-base.","Interromper exames após uma glicemia próxima de 200 mg/dL.","Monitorizar glicemia, eletrólitos, acidose, diurese e neurologia."],"answer":4,"analysis":["INCORRETA. K e Na podem mudar rapidamente.","INCORRETA. Resolução bioquímica nem sempre acompanha glicemia.","INCORRETA. SpO₂ avalia oxigenação, não CAD.","INCORRETA. A acidose pode persistir.","CORRETA. CAD exige vigilância integrada de distúrbios metabólicos, volume e lesão cerebral durante a correção."],"explanation":"CAD exige vigilância integrada de distúrbios metabólicos, volume e lesão cerebral durante a correção.","memorizar":"CAD: monitorar GLICOSE + K/Na + GAP/CETONAS + PERFUSÃO + NEUROLOGIA.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"monitorização seriada","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"difícil"},{"id":"ouro-rigor5-sc-A8-30","topicId":"sc-A8","stem":"Adolescente com CAD e choque hipovolêmico mantém lactato alto apesar de iniciar insulina. Gasometria apresenta acidose importante. Qual interpretação ajuda a explicar a acidose além das cetonas?","options":["Acidose láctica por hipoperfusão associada à cetoacidose.","Todo lactato alto prova ausência de CAD e exige descartar cetonemia.","A insulina isolada corrige imediatamente toda hipoperfusão circulatória.","O lactato é específico de meningite bacteriana, não de choque.","Choque hipovolêmico aumenta necessariamente perfusão periférica e reduz lactato."],"answer":0,"analysis":["CORRETA. A acidose metabólica pode ter mais de uma fonte: cetoácidos e lactato por hipoperfusão.","INCORRETA. Cetoacidose e acidose láctica podem coexistir.","INCORRETA. Perfusão depende também da volemia e da causa do choque.","INCORRETA. Lactato sobe em hipoperfusão de diferentes causas.","INCORRETA. Choque piora oferta tecidual de oxigênio."],"explanation":"A acidose metabólica pode ter mais de uma fonte: cetoácidos e lactato por hipoperfusão.","memorizar":"CAD + CHOQUE pode ter CETOÁCIDOS e LACTATO simultaneamente.","source":"Biblioteca Trilha de Ouro SDCII A8 CAD; elaboração autoral; condutas detalhadas devem ser confirmadas em protocolo pediátrico vigente antes de uso assistencial.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Cetoacidose diabética pediátrica","group":"P2 • Saúde da Criança II","competence":"acidose lactica associada","kind":"case","reviewStatus":"revisão técnica editorial local; fonte clínica específica e atualização de diretrizes requerem checagem independente","degree":"muito difícil"}]};
